# Test input
test_in = [
    [0,0,3,0,0,8,0,0],   # row 0
    [0,0,0,2,2,0,0,0],   # row 1 - block starts
    [0,0,0,2,2,0,0,0],   # row 2 - block ends  
    [0,0,7,0,0,6,0,0],   # row 3
    [7,0,0,6,0,0,0,0],   # row 4
    [0,2,2,0,0,0,0,0],   # row 5
    [0,2,2,0,0,0,0,0],   # row 6
    [8,0,0,3,0,0,0,0]    # row 7
]

def solve(grid):
    rows, cols = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Find first block of 2s
    block_r, block_c = None, None
    for r in range(rows-1):
        for c in range(cols-1):
            if grid[r][c]==2 and grid[r+1][c]==2 and grid[r][c+1]==2 and grid[r+1][c+1]==2:
                block_r, block_c = r, c
                break

    if block_r is None:
        return grid

    # Copy block
    for r in range(block_r, block_r+2):
        for c in range(block_c, block_c+2):
            result[r][c] = grid[r][c]

    # Find source values in each quadrant
    tl_val = tr_val = bl_val = br_val = 0

    # Scan for sources
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                if r >= block_r and r <= block_r+1 and c >= block_c and c <= block_c+1:
                    continue  # skip block

                # Determine quadrant
                if r < block_r and c < block_c:
                    if tl_val == 0:
                        tl_val = grid[r][c]
                elif r < block_r and c > block_c+1:
                    if tr_val == 0:
                        tr_val = grid[r][c]
                elif r > block_r+1 and c < block_c:
                    if bl_val == 0:
                        bl_val = grid[r][c]
                elif r > block_r+1 and c > block_c+1:
                    if br_val == 0:
                        br_val = grid[r][c]

    print(f"Sources: TL={tl_val}, TR={tr_val}, BL={bl_val}, BR={br_val}")

    # Fill diagonals with CROSS mapping
    # TL val → TR diagonal (top-right, going SW from (0, cols-1))
    # TR val → BR diagonal (bottom-right, going NW from (rows-1, cols-1))
    # BL val → TL diagonal (top-left, going SE from (0, 0))
    # BR val → BL diagonal (bottom-left, going NE from (rows-1, 0))

    # TL diagonal: from (0,0) going SE
    v = bl_val
    r, c = 0, 0
    while r < rows and c < cols:
        if result[r][c] == 0:  # Only fill zeros (don't overwrite block or existing values)
            result[r][c] = v
            r += 1; c += 1
        else:
            break

    # TR diagonal: from (0, cols-1) going SW
    v = tl_val
    r, c = 0, cols - 1
    while r < rows and c >= 0:
        if result[r][c] == 0:
            result[r][c] = v
            r += 1; c -= 1
        else:
            break

    # BL diagonal: from (rows-1, 0) going NE
    v = br_val
    r, c = rows - 1, 0
    while r >= 0 and c < cols:
        if result[r][c] == 0:
            result[r][c] = v
            r -= 1; c += 1
        else:
            break

    # BR diagonal: from (rows-1, cols-1) going NW
    v = tr_val
    r, c = rows - 1, cols - 1
    while r >= 0 and c >= 0:
        if result[r][c] == 0:
            result[r][c] = v
            r -= 1; c -= 1
        else:
            break

    return result

